export interface Entry {
  id: string
  ro: string
  en: string
  he: string
  /** category slug */
  cat: string
  /** difficulty tier: 1 survival, 2 everyday, 3 expanding */
  tier: 1 | 2 | 3
  /** hand-written pronunciation hint; auto-generated when absent */
  hint?: string
}

function e(
  ro: string,
  en: string,
  he: string,
  cat: string,
  tier: 1 | 2 | 3,
  hint?: string,
): Entry {
  const id = `${cat}:${ro}`
    .toLowerCase()
    .normalize('NFD')
    .replace(/[̀-ͯ]/g, '')
    .replace(/[^a-z0-9]+/g, '-')
    .replace(/^-|-$/g, '')
  return { id, ro, en, he, cat, tier, hint }
}

